      const look: Look = k < 900 ? 'left' : k < 1300 ? 'ahead' : k < 2200 ? 'right' : 'ahead'
      clawd(c, { look: look, left: stretch ? 'out' : 'side', right: stretch ? 'out' : 'side' })
      dots(c, [[20, 5], [23, 5], [26, 5]], C.white)
