      rect(c, 20, 5, 8, 1, C.paper)
      if (k > 600) dots(c, [[23, 5], [24, 5]], C.stamp)
      rect(c, 22, down ? 3 : 1, 4, 1, C.stamp)
      rect(c, 23, down ? 1 : 0, 2, down ? 2 : 1, C.roll)
    },
  },

  ciBuild: {
    ms: 900,
    draw(c, t) {
      const k = t % 900
      const strike = k > 520
      clawd(c, { look: 'right', right: 'out' })
      rect(c, 21, 4, 6, 1, C.anvil)
      rect(c, 22, 5, 4, 1, C.anvil)
