      "description": "Race Codemagic and GitHub Actions builds above the prompt and alert when they finish",
      "default": true
    },
    "continueAfterBuilds": {
      "type": "boolean",
      "title": "Let Claude continue after builds",
      "description": "When a build finishes in this session's repo, send Claude the result as a new prompt (with the failure log when it fails). Off keeps the race and the alerts.",
      "default": true
    },
    "ntfyTopic": {
      "type": "string",
      "title": "ntfy topic",
      "description": "Private ntfy.sh topic for phone pushes when a build finishes. Leave empty to turn phone pushes off.",
      "sensitive": true,
      "default": ""
    },
    "bridge": {
      "type": "boolean",
      "title": "Feed Clawd on Desk",
      "description": "Forward session events to the Clawd on Desk app in place of its per-event command hooks. It holds off while those hooks are installed; /clawd desk swaps them over",
      "default": true
    },
    "clawdInstallDir": {
      "type": "string",
      "title": "Clawd on Desk app folder",
      "description": "Leave empty to find it automatically. Otherwise the installed app's resources/app.asar.unpacked folder",
      "default": ""
    },
    "nodePath": {
      "type": "string",
      "title": "Node.js executable",
      "description": "Runs the bridge sidecar",
      "default": "node"
    }
  }
}
